    (hf : ContinuousOn f (Ioo 0 1)) {a b : ℝ}
    (ha : a ∈ Ioo (0 : ℝ) 1) (hb : b ∈ Ioo (0 : ℝ) 1) :
    (∀ z ∈ Ioo (0 : ℝ) 1, d4BMPlusPlusContinuousGreenResponse n chi f a b z = 0) ↔
      ∀ z ∈ Ioo (0 : ℝ) 1, f z = 0

